import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { PDFDocument, StandardFonts, rgb, type PDFFont, type PDFPage } from 'pdf-lib';

// All source content is invented. Fixed metadata makes regenerated bytes stable.
const seller = 'Tavlune Fasteners (Fictional)';
const ink = rgb(0.12, 0.17, 0.22);
const muted = rgb(0.38, 0.43, 0.48);

function write(page: PDFPage, font: PDFFont, text: string, x: number, y: number, size = 11) {
  page.drawText(text, { x, y, size, font, color: ink });
}

async function document() {
  const pdf = await PDFDocument.create();
  pdf.setTitle('Fictional purchase order - po-extraction-demo');
  pdf.setAuthor('po-extraction-demo');
  pdf.setCreator('po-extraction-demo sample generator');
  pdf.setProducer('po-extraction-demo');
  pdf.setCreationDate(new Date('2026-01-01T00:00:00Z'));
  pdf.setModificationDate(new Date('2026-01-01T00:00:00Z'));
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  return { pdf, font, bold };
}

function heading(page: PDFPage, font: PDFFont, bold: PDFFont, buyer: string, number: string, pageLabel: string) {
  page.drawRectangle({ x: 40, y: 720, width: 532, height: 35, color: rgb(0.92, 0.95, 0.97) });
  write(page, bold, 'PURCHASE ORDER', 52, 732, 17);
  write(page, font, number, 430, 734, 11);
  write(page, bold, buyer, 52, 690, 13);
  write(page, font, `Supplier: ${seller}`, 52, 666);
  write(page, font, `Currency: USD  |  ${pageLabel}`, 52, 644);
  page.drawText('FICTIONAL SAMPLE - no real transaction or contact details', {
    x: 52, y: 44, size: 9, font, color: muted,
  });
}

async function tablePDF() {
  const { pdf, font, bold } = await document();
  const page = pdf.addPage([612, 792]);
  heading(page, font, bold, 'Velquora Assembly (Fictional)', 'VEL-1101', 'Page 1 of 1');
  const columns = [52, 82, 184, 410, 452, 510];
  const headers = ['Line', 'Supplier SKU', 'Description', 'Qty', 'USD/ea', 'USD'];
  headers.forEach((label, i) => write(page, bold, label, columns[i]!, 594, 10));
  const rows = [
    ['1', 'BLT-M8-Z', 'Hex bolt M8 zinc plated', '200', '0.45', '90.00'],
    ['2', 'NUT-M8-Z', 'Hex nut M8 zinc plated', '200', '0.18', '36.00'],
    ['3', 'WSH-M8-Z', 'Flat washer M8 zinc plated', '400', '0.08', '32.00'],
  ];
  rows.forEach((row, i) => {
    const y = 562 - i * 42;
    page.drawLine({ start: { x: 52, y: y + 20 }, end: { x: 560, y: y + 20 }, thickness: 0.5, color: muted });
    row.forEach((cell, j) => write(page, font, cell, columns[j]!, y, 10));
  });
  write(page, font, 'All quantities are each. No substitutions.', 52, 414);
  write(page, bold, 'Order total: USD 158.00', 366, 370, 13);
  write(page, font, 'Please prepare a quote for human review before fulfillment.', 52, 316, 10);
  await writeFile('samples/table-po.pdf', await pdf.save({ useObjectStreams: false }));
}

async function multipagePDF() {
  const { pdf, font, bold } = await document();
  const first = pdf.addPage([612, 792]);
  heading(first, font, bold, 'Nimbrel Workshop (Fictional)', 'NIM-3303', 'Page 1 of 2');
  write(first, bold, 'Workshop replenishment / section A', 52, 592, 14);
  write(first, bold, '1. BLT-M10-Z - Hex bolt M10 zinc plated', 52, 540);
  write(first, font, 'Quantity: 50 each   |   Unit price: USD 0.68   |   Amount: USD 34.00', 66, 514, 10);
  write(first, bold, '2. SCR-M4-S - Socket cap screw M4 stainless steel', 52, 450);
  write(first, font, 'Quantity: 2 boxes   |   Unit price: USD 8.25   |   Amount: USD 16.50', 66, 424, 10);
  write(first, font, 'Page subtotal: USD 50.50. This is not an order line.', 52, 330);
  write(first, bold, 'CONTINUED ON PAGE 2 - two further order lines follow.', 52, 272, 11);
  const second = pdf.addPage([612, 792]);
  heading(second, font, bold, 'Nimbrel Workshop (Fictional)', 'NIM-3303', 'Page 2 of 2');
  write(second, font, 'Carry-forward: USD 50.50 (informational only)', 52, 598);
  write(second, bold, '3. TIE-200-B - Cable tie 200mm black', 52, 540);
  write(second, font, 'Quantity: 5 packs   |   Unit price: USD 4.50   |   Amount: USD 22.50', 66, 514, 10);
  write(second, bold, '4. Flat washer M8', 52, 450);
  write(second, font, 'Quantity: 300 each. Finish unspecified; price not supplied.', 66, 424, 10);
  write(second, font, 'Confirm zinc plated or stainless steel before accepting line 4.', 66, 402, 10);
  write(second, bold, 'Known-price subtotal: USD 73.00; line 4 requires a quote.', 52, 318, 12);
  write(second, font, 'Do not count page headers, subtotals, or carry-forwards as items.', 52, 272, 10);
  await writeFile('samples/multipage-po.pdf', await pdf.save({ useObjectStreams: false }));
}

await mkdir('samples', { recursive: true });
await tablePDF();
await multipagePDF();
// Only update integrity bindings. Recorded extraction data is hand-authored and retained.
const samples: { file: string; fixture: string }[] = JSON.parse(await readFile('samples/manifest.json', 'utf8'));
for (const sample of samples) {
  const fixture = JSON.parse(await readFile(sample.fixture, 'utf8'));
  fixture.sourceSha256 = createHash('sha256').update(new Uint8Array(await readFile(sample.file))).digest('hex');
  await writeFile(sample.fixture, JSON.stringify(fixture, null, 2) + '\n');
}
console.log('Generated 1-page table and 2-page narrative PDFs; refreshed three fixture checksums.');
